      {k: 'fact', t: 'هرمُ الطاقةِ', pg: '١١٦', x: 'المستوَى الثَّانِي فِي الهرمِ يوضّحُ المستهلكاتِ؛ حيثُ تستهلكُ كميّاتٍ كبيرةً لِتَبْقَى عَلَى قيدِ الحياةِ. وتمثّلُ القوارتُ المستوياتِ الأُخْرَى منَ الهرمِ الغذائيّ.', img: 'energy_pyramid'},
      {k: 'discuss', t: 'التفكيرُ الناقدُ', pg: '١١٦', x: 'السلسلةُ الغذائيّةُ فِي المحيطِ تَحْتَوِي عَلَى مخلوقاتٍ حيّةٍ آكلةٍ للحومِ أكثرَ منَ السلسلةِ عَلَى اليابسةِ. لِمَاذَا؟'},
      {k: 'vocab', t: 'المفرداتُ', pg: '١١٧', x: 'مَا المحلّلات؟ أَعْطِي أمثلةً عَلَيْهَا.', a: 'تحلّلُ الموادَّ الميّتةَ وتعيدُها إِلَى النظامِ البيئيّ عَلَى شكلِ موادَّ مغذّية؛ مِثْلُ الديدانِ والبَكْتِيرِيَا والفطريّات.'},
      {k: 'discuss', t: 'أستنتجُ', pg: '١١٧', x: 'قامَ عددٌ منَ العلماءِ بحصرِ آكلاتِ الأعشابِ وآكلاتِ اللحومِ فِي نظامٍ بيئيّ، وَوَجَدُوا أنّ عددَ آكلاتِ اللحومِ يفوقُ عددَ آكلاتِ الأعشابِ. فَهَلْ يُعدُّ هَذَا التعدادُ للحيواناتِ فِي المنطقةِ كاملًا؟ لِمَاذَا؟', head: ['أدلّةٌ منَ النصّ', 'استنتاجاتٌ'], rows: [['', '']]},
      {k: 'discuss', t: 'التفكيرُ الناقدُ', pg: '١١٧', x: 'لِمَاذَا تكونُ أسنانُ آكلاتِ اللحومِ حادّةً جدًّا مقارنةً بأسنانِ آكلاتِ الأعشابِ؟'},
      {k: 'discuss', t: 'السؤالُ الأساسيّ', pg: '١١٧', x: 'كيفَ تحصلُ المخلوقاتُ الحيّةُ عَلَى الطاقةِ؟'},
      {k: 'math', t: 'العلومُ والرياضيّات: أحسبُ عددَ آكلاتِ اللحومِ', pg: '١١٧', x: 'فِي النظامِ البيئيّ الطبيعيّ تكونُ أعدادُ آكلاتِ الأعشابِ ١٠ أضعافِ آكلاتِ اللحومِ. أحسبُ عددَ آكلاتِ اللحومِ الَّتِي قَدْ أجدُها فِي نظامٍ بيئيّ يبلغُ عددُ آكلاتِ الأعشابِ فِيهِ ٤٢٥٠.', a: '٤٢٥٠ ÷ ١٠ = ٤٢٥.'},
      {k: 'write', t: 'العلومُ والفنّ: أرسمُ شبكةً غذائيّة', pg: '١١٧', x: 'أبحثُ عَنْ مخلوقاتٍ حيّةٍ فِي بيئتِي، ثُمَّ أعملُ ملصقًا أوضّحُ فِيهِ شبكةً غذائيّةً ترتبطُ فِيهَا هَذِهِ المخلوقاتُ.'},
      {k: 'skill', t: 'أنظّمُ أَفْكَارِي: المطويّات', pg: '١١٧', x: 'أعملُ مطويّةً كالمبيّنةِ فِي الشكلِ، ألخّصُ فِيهَا مَا تعلّمتُه عنِ العلاقاتِ فِي الأنظمةِ البيئيّة. عناوينُ الطبقاتِ: المنتجاتُ والمستهلكاتُ والمحلّلات، السلاسلُ والشبكاتُ الغذائيّة، هرمُ الطاقةِ.'}
